typedef unsigned int U32;

U32 A = 10;
// Global variable A (type U32)

struct A { float x; };
// Struct tag A (namespace separate from typedef/variable)

void test_shadow(U32 A) {
    // Parameter A (type U32, shadows global variable A)

    struct A instance_a;
    // Uses struct tag A

    {
        int A = 5;
        // Local variable A (type int, shadows parameter A)
        // Global A is unreachable by name lookup here.
    }
}

